"""Shipped artifacts must match what the current code computes.

WHY THIS EXISTS
---------------
Twice in one cycle a stale artifact was mistaken for a live one:

* ``formula_renders.json`` — an early version of the render test loaded the
  gitignored build-scratch copy at the repo root and cheerfully validated a
  three-day-old bundle that predated the fix it was meant to check. Three
  tests passed against data written before the code existed.
* ``AutoGenerated/`` under ``simulations/`` was a Windows junction pointing
  at a temp directory from a previous run, so anything writing through the
  legacy path landed somewhere nothing ever read.

Both were invisible because *the artifact looked fine*. A JSON file with
plausible numbers gives no hint of its age, and every downstream consumer —
the website, the paper, these tests — trusts it.

The guard is to RECOMPUTE. Each check below derives a value from the live
code and compares it to the shipped file. If someone edits the physics and
does not rebuild, these fail; if the build is current, they cost
milliseconds. They deliberately compare structural invariants rather than
floating-point payloads, so a legitimate numerical refinement does not
produce noise, but a structural drift cannot hide.
"""
from __future__ import annotations

import json
import os
from pathlib import Path

import pytest


def _autogen() -> Path:
    """The PUBLISHED artifact directory, not the build scratch copy."""
    raw = os.environ.get("METAPHYSICA_OUT")
    candidates = []
    if raw:
        candidates.append(Path(raw) / "AutoGenerated")
    candidates += [
        Path("H:/Github/PrincipiaMetaphysica/AutoGenerated"),
        Path(__file__).resolve().parents[1] / "AutoGenerated",
    ]
    for path in candidates:
        if path.is_dir():
            return path
    pytest.skip("no AutoGenerated directory found; run the build first")


def _load(name: str) -> dict:
    path = _autogen() / name
    if not path.is_file():
        pytest.skip(f"{name} not present; run the build first")
    return json.loads(path.read_text(encoding="utf-8"))


# ── topological flux: the Stage-4 physics result ────────────────────────────


def test_shipped_coupling_graph_matches_recomputation():
    """The seven-triangle structure is recomputed, not trusted.

    This is the artifact behind the bridge-channel proposal. If phi or the
    selection rule changes and the report is not regenerated, the published
    claim silently describes a geometry the code no longer produces.
    """
    from metaphysica.simulations.PM.gauge.topological_terms import coupling_graph

    shipped = _load("topological_flux.json").get("coupling_graph")
    if shipped is None:
        pytest.skip("coupling_graph absent; regenerate topological_flux.json")
    live = coupling_graph()
    assert shipped["n_vertices"] == live["n_vertices"]
    assert shipped["n_edges"] == live["n_edges"]
    assert shipped["is_two_regular"] == live["is_two_regular"]
    assert shipped["component_sizes"] == live["component_sizes"]


def test_shipped_selection_rule_matches_recomputation():
    from metaphysica.simulations.PM.gauge.topological_terms import allowed_channels

    shipped = _load("topological_flux.json")["selection_rule"]
    live = allowed_channels()
    assert shipped["n_allowed"] == live["n_allowed"]
    assert shipped["n_disjoint_placements"] == live["n_disjoint_placements"]


def test_shipped_flux_density_matches_recomputation():
    """The headline number itself, recomputed from the stabilised vacuum."""
    from metaphysica.simulations.PM.geometry.bridge_geometry import BridgeSystem
    from metaphysica.simulations.PM.gauge.topological_terms import (
        area_two_form,
        cs7_result,
    )

    shipped = _load("topological_flux.json")
    moduli, _ = BridgeSystem().stabilize_moduli()
    L1, L2, theta = (float(v) for v in moduli[0])
    live = cs7_result(
        area_two_form(L1, L2, theta, 0, 1),
        area_two_form(L1, L2, theta, 3, 6),
    )
    assert live.density_via_epsilon == pytest.approx(
        shipped["density_via_epsilon"], rel=1e-9
    ), "published flux density does not match the current code -- rebuild"


# ── gate certificates ───────────────────────────────────────────────────────


def test_shipped_certificate_counts_match_their_own_records():
    """The summary must agree with the certificates it summarises.

    A hand-edited summary, or a partial regeneration, would otherwise report
    a scoreboard nothing backs.
    """
    bundle = _load("GATES_CERTIFICATES.json")
    certs = bundle["certificates"]
    summary = bundle["evaluation_summary"]
    for key, status in (("computed_pass", "COMPUTED_PASS"),
                        ("computed_fail", "COMPUTED_FAIL"),
                        ("declarative", "DECLARATIVE")):
        actual = sum(1 for c in certs if c.get("evaluation_status") == status)
        assert summary[key] == actual, (
            f"summary says {key}={summary[key]} but {actual} certificates "
            f"carry {status}"
        )


def test_semantic_gates_still_evaluate_the_same_way():
    """Recompute every promoted gate and compare to the shipped certificate."""
    from metaphysica.generators.generate_72_certificates import evaluate_gate
    from metaphysica.simulations.PM.validation.declarative_strategies\
        .strategy_a_semantic import SEMANTIC_EVALUATORS

    certs = {c["gate_id"]: c for c in _load("GATES_CERTIFICATES.json")["certificates"]}
    params = _load("parameters.json")["parameters"]
    for gate_id in sorted(SEMANTIC_EVALUATORS):
        shipped = certs.get(gate_id)
        if shipped is None:
            continue
        live = evaluate_gate(gate_id, {}, params)
        assert live["status"] == shipped["evaluation_status"], (
            f"G{gate_id:02d}: code says {live['status']}, artifact says "
            f"{shipped['evaluation_status']} -- rebuild"
        )


def test_g72_seal_reflects_the_gates_it_aggregates():
    """The seal must fail when any gate it covers fails.

    G72 was once an asserted seal that passed regardless. It now aggregates,
    and this checks the aggregation is real rather than restated.
    """
    bundle = _load("GATES_CERTIFICATES.json")
    certs = {c["gate_id"]: c for c in bundle["certificates"]}
    seal = certs.get(72)
    if seal is None or "evaluation" not in seal:
        pytest.skip("G72 has no evaluation record")
    failing = sorted(
        gid for gid, c in certs.items()
        if gid != 72 and c.get("evaluation_status") == "COMPUTED_FAIL"
    )
    assert seal["evaluation"].get("failed_gates") == failing
    expected = "COMPUTED_FAIL" if failing else "COMPUTED_PASS"
    assert seal["evaluation_status"] == expected


