def test_shipped_reference_audit_matches_recomputation():
    from metaphysica.generators.generate_reference_integrity import audit_references

    shipped = _load("reference_integrity.json")
    live = audit_references(_autogen())
    assert live["totals"]["references"] == shipped["totals"]["references"]
